\"use client\";

import { useMutation, useQueryClient } from \"@tanstack/react-query\";
import { duplicateWebhookApi } from \"@/modules/integrations/webhooks/lib/api-client\";

/**
 * Hook that duplicates a webhook via the v3 API and invalidates the webhook list cache.
 *
 * Callers supply the query key for the list that contains the webhook; on success the
 * hook invalidates it so the server fetch picks up the new row.
 */
export const useDuplicateWebhookMutation = ({
  queryKey,
}: {
  queryKey: unknown;
}) => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ webhookId }: { webhookId: string }) =>
      duplicateWebhookApi(webhookId),
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey });
    },
  });
};
ENDOFFILE"

